#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

/*
 * Define a memory slab for testing.
 * SLAB_BLOCK_SIZE: Size of each memory block in bytes.
 * SLAB_NUM_BLOCKS: Total number of blocks in the slab.
 * 4: Alignment requirement (e.g., 4 bytes).
 */
#define SLAB_BLOCK_SIZE 64
#define SLAB_NUM_BLOCKS 2 /* Using a small number of blocks for easy exhaustion testing */

K_MEM_SLAB_DEFINE(mslab1, SLAB_BLOCK_SIZE, SLAB_NUM_BLOCKS, 4);

/* Array to hold pointers to allocated blocks for cleanup */
static void *blocks[SLAB_NUM_BLOCKS];

/**
 * @brief Test k_mem_slab_alloc with timeout expecting -EAGAIN
 *
 * This test case verifies that k_mem_slab_alloc correctly returns -EAGAIN
 * when the memory slab is fully exhausted and a timeout is specified.
 * It first allocates all available blocks, then attempts a timed allocation
 * which should fail with -EAGAIN.
 */
ZTEST(mslab_concept, test_mslab_alloc_wait_timeout)
{
    void *block;
    int ret;

    /* 1. Exhaust the memory slab by allocating all available blocks. */
    for (int i = 0; i < SLAB_NUM_BLOCKS; i++) {
        ret = k_mem_slab_alloc(&mslab1, &blocks[i], K_NO_WAIT);
        zassert_equal(ret, 0, "Failed to allocate block %d initially. Returned %d", i, ret);
        zassert_not_null(blocks[i], "Allocated block %d is NULL", i);
    }

    /* 2. Attempt to allocate another block with a timeout.
     * Since the slab is exhausted, this call should time out and return -EAGAIN.
     * K_MSEC(100) is a reasonable timeout for a test.
     */
    ret = k_mem_slab_alloc(&mslab1, &block, K_MSEC(100));
    zassert_equal(ret, -EAGAIN, "k_mem_slab_alloc did not return -EAGAIN on timeout. Returned %d", ret);

    /* 3. Free all allocated blocks to clean up the slab for subsequent tests. */
    for (int i = 0; i < SLAB_NUM_BLOCKS; i++) {
        k_mem_slab_free(&mslab1, blocks[i]);
        blocks[i] = NULL; /* Clear pointer after freeing */
    }
}

/*
 * Other test functions for mslab_concept might be here.
 * For example, tests for k_mem_slab_alloc with K_FOREVER, k_mem_slab_free, etc.
 * The error log only points to test_mslab_alloc_wait_timeout.
 */

/* Define the test suite */
ZTEST_SUITE(mslab_concept, NULL, NULL, NULL, NULL, NULL);
